        .await;

        assert_eq!(status, StatusCode::MULTI_STATUS);
        assert!(resp.contains(&foreign_href));
        assert!(resp.contains("HTTP/1.1 404 Not Found"));
        assert!(
            !resp.contains("Real Event"),
